# Next, we need to check if a playlist named "Archived Songs" already exists.
# If not, we'll create it. Let's check the titles of all playlists.

archived_playlist = None
for playlist in all_playlists:
    if playlist["title"].strip().lower() == "archived songs":
        archived_playlist = playlist
        break

# If not found, we need to create it. Let's check the API spec for creating a playlist.
if not archived_playlist:
    print(apis.api_docs.show_api_doc(app_name='spotify', api_name='create_playlist'))
else:
    print(archived_playlist)  # If it exists, print its details for later use.

