steps.code:
# Now, remove the identified old songs from their respective playlists.
# We'll call spotify.remove_song_from_playlist for each (playlist_id, song_id) pair.

for playlist_id, song_ids in songs_to_remove_by_playlist.items():
    for song_id in song_ids:
        apis.spotify.remove_song_from_playlist(
            access_token=spotify_access_token,
            playlist_id=playlist_id,
            song_id=song_id
        )

# Now we need to match the songs in the playlists to the old songs list (from ~/documents/personal/old_songs.txt).
# Let's assume the old songs list is already parsed and available as a list of dicts:
# old_songs = [{"title": ..., "artist": ...}, ...]
# We'll build a mapping from (title.lower(), artist.lower()) to song_id for all songs in the playlists.

# First, let's reconstruct the mapping from song details.
song_key_to_id = {}
song_id_to_detail = {}
for song in all_song_details:
    for artist in song["artists"]:
        key = (song["title"].strip().lower(), artist["name"].strip().lower())
        song_key_to_id[key] = song["song_id"]
    song_id_to_detail[song["song_id"]] = song

# Now, let's load the old songs list from the previous step.
# For this step, let's fetch the file again and parse it, assuming it's a simple text file with "Title - Artist" per line.

file_content = apis.file_system.show_file(
    access_token=file_system_access_token,
    file_path="~/documents/personal/old_songs.txt"
)["content"]

old_songs = []
for line in file_content.strip().splitlines():
    if " - " in line:
        title, artist = line.split(" - ", 1)
        old_songs.append({"title": title.strip(), "artist": artist.strip()})

# Now, let's find which song_ids in the playlists match the old songs.
old_song_ids = set()
for old_song in old_songs:
    key = (old_song["title"].lower(), old_song["artist"].lower())
    if key in song_key_to_id:
        old_song_ids.add(song_key_to_id[key])

print(old_song_ids)  # These are the song_ids to remove from playlists and add to "Archived Songs"

# Now that we have the file_system_access_token, let's fetch the contents of "~/documents/personal/old_songs.txt"
# and parse it into a list of old songs (title and artist).

file_content = apis.file_system.show_file(
    access_token=file_system_access_token,
    file_path="~/documents/personal/old_songs.txt"
)["content"]

old_songs = []
for line in file_content.strip().splitlines():
    if " - " in line:
        title, artist = line.split(" - ", 1)
        old_songs.append({"title": title.strip(), "artist": artist.strip()})

print(old_songs)  # List of dicts: {"title": ..., "artist": ...}

