steps.code:
# Let's collect all the old song Spotify IDs and check which playlists contain them.
# We'll build a mapping: playlist_id -> list of old song IDs to remove from that playlist.

old_song_ids = set(song["spotify_song_id"] for song in json_friendly_mapping)
playlist_removals = {}

for playlist in all_playlists:
    to_remove = [song_id for song_id in playlist["song_ids"] if song_id in old_song_ids]
    if to_remove:
        playlist_removals[playlist["playlist_id"]] = to_remove

print(playlist_removals)

