steps.code:
# The search results show that the first result for each query is an exact match (title and artist).
# I will now search for all songs in songs_to_archive and collect their song_ids by matching both title and artist exactly.

def extract_title_and_artist(song_str):
    # Format: "<title> by <artist>"
    if " by " in song_str:
        title, artist = song_str.rsplit(" by ", 1)
        return title.strip(), artist.strip()
    return song_str.strip(), None

archive_song_ids = []
archive_song_id_to_info = {}

for song_str in songs_to_archive:
    title, artist = extract_title_and_artist(song_str)
    results = apis.spotify.search_songs(
        access_token=spotify_access_token,
        query=song_str,
        page_limit=5
    )
    # Find the first result with exact title and artist match
    found = False
    for song in results:
        song_title = song["title"].strip().lower()
        song_artists = [a["name"].strip().lower() for a in song["artists"]]
        if song_title == title.strip().lower() and artist and artist.strip().lower() in song_artists:
            archive_song_ids.append(song["song_id"])
            archive_song_id_to_info[song["song_id"]] = {"title": song["title"], "artist": artist}
            found = True
            break
    if not found:
        archive_song_id_to_info[song_str] = None  # Mark as not found

print(archive_song_ids)
print(archive_song_id_to_info)

