steps.code:
# The show_song API takes a song_id and returns details including title and artists.
# Let's fetch the metadata (title and artist names) for all unique_song_ids.
# We'll build a mapping from song_id to (title, artist_names) for later matching.

song_id_to_metadata = {}
for song_id in unique_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if "title" in song and "artists" in song:
        artist_names = [artist["name"] for artist in song["artists"]]
        song_id_to_metadata[song_id] = {
            "title": song["title"],
            "artists": artist_names
        }
print(song_id_to_metadata)

