steps.code:
# Let's parse the `songs_to_archive` list into a list of dicts with "title" and "artist" for easier matching.
# Then, for each song in our Spotify library, we'll check if its title and any of its artists match an entry in the archive list.
# We'll collect the song_ids that need to be archived.

def parse_song_entry(entry):
    # Format: "<title> by <artist>"
    if " by " in entry:
        title, artist = entry.rsplit(" by ", 1)
        return {"title": title.strip(), "artist": artist.strip()}
    return None

archive_entries = [parse_song_entry(entry) for entry in songs_to_archive if parse_song_entry(entry)]

# Now, find song_ids in song_id_to_metadata that match any archive entry (title and artist)
songs_to_archive_ids = []
for song_id, meta in song_id_to_metadata.items():
    for entry in archive_entries:
        if meta["title"] == entry["title"] and entry["artist"] in meta["artists"]:
            songs_to_archive_ids.append(int(song_id))
            break

print(songs_to_archive_ids)  # These are the song_ids to remove from playlists and add to "Old Songs"

