# Now let's fetch the release month for each song missing it.
# We'll use the spotify.search_songs API with a query combining the song title and artist.
# We'll collect the release month info for each song.

release_months = []

for entry in missing_release_month:
    query = f"{entry['song_title']} {entry['artist']}"
    # Only fetch the top result (page_limit=1)
    result = apis.spotify.search_songs(query=query, page_limit=1)
    if result and isinstance(result, list) and len(result) > 0:
        song_info = result[0]
        release_date = song_info.get("release_date")
        if release_date:
            # Extract year and month
            year_month = release_date[:7]  # "YYYY-MM"
            release_months.append({
                "line": entry["line"],
                "song_title": entry["song_title"],
                "artist": entry["artist"],
                "release_month": year_month
            })
        else:
            release_months.append({
                "line": entry["line"],
                "song_title": entry["song_title"],
                "artist": entry["artist"],
                "release_month": None
            })
    else:
        release_months.append({
            "line": entry["line"],
            "song_title": entry["song_title"],
            "artist": entry["artist"],
            "release_month": None
        })

release_months  # List of dicts with release month info for each song missing it

# Now let's update the note content by adding the release month info for each song that was missing it.
# We'll replace each line in the note that was missing release month info with a new line that includes it in the format:
# "Song Title - Artist Name (Release Month: YYYY-MM)"
# If release month could not be found, we'll leave the line unchanged.

updated_lines = []
release_month_map = {entry["line"]: entry for entry in release_months}

for line in note_content.splitlines():
    if line in release_month_map:
        entry = release_month_map[line]
        if entry["release_month"]:
            new_line = f"{entry['song_title']} - {entry['artist']} (Release Month: {entry['release_month']})"
            updated_lines.append(new_line)
        else:
            updated_lines.append(line)  # Could not find release month, leave unchanged
    else:
        updated_lines.append(line)

updated_note_content = "\n".join(updated_lines)
print(updated_note_content)  # Show the updated note content before saving

