    search_result = result["search_result"]
    if isinstance(search_result, list) and len(search_result) > 0:
        song = search_result[0]
        release_date = song.get("release_date")
        if release_date:
            # Extract YYYY-MM from release_date (format: YYYY-MM-DDTHH:MM:SS)
            release_month = release_date[:7]
            release_month_updates.append({
                "entry": entry,
                "release_month": release_month
            })
        else:
            release_month_updates.append({
                "entry": entry,
                "release_month": None
            })
    else:
        release_month_updates.append({
            "entry": entry,
            "release_month": None
        })

