steps.code:
# Let's update the note content by replacing each "RELEASED_AT TODO" with the correct release month from the release_months dictionary.
import re

def replace_release_months(note_content, release_months):
    def replacer(match):
        title = match.group(1).strip()
        month = release_months.get(title)
        if month:
            return f"{title} BY{match.group(2)}RELEASED_AT {month}"
        else:
            # If not found, keep as TODO
            return match.group(0)
    # Regex to match lines with "TITLE BY ... RELEASED_AT TODO"
    pattern = re.compile(r"^(.*?) BY(.*?)RELEASED_AT TODO", re.MULTILINE)
    return pattern.sub(replacer, note_content)

updated_content = replace_release_months(note_content, release_months)
print(updated_content)

